const ACTION_ID_PATTERN = /^[a-z][a-z0-9_-]*(?:\.[a-z][a-z0-9_-]*)+$/;

export function generateTypeScriptClient(manifest) {
  if (!manifest || !Array.isArray(manifest.actions)) {
    throw new Error("TypeScript generation requires a Manifest actions array.");
  }
  const actions = [...manifest.actions].sort((left, right) => left.id.localeCompare(right.id));
  const symbols = new Map();
  for (const action of actions) {
    if (!ACTION_ID_PATTERN.test(action.id)) {
      throw new Error(`Cannot generate a TypeScript symbol for invalid Action ID: ${action.id}`);
    }
    const symbol = actionSymbol(action.id);
    const previous = symbols.get(symbol);
    if (previous) {
      throw new Error(`Action IDs ${previous} and ${action.id} both generate TypeScript symbol ${symbol}.`);
    }
    symbols.set(symbol, action.id);
  }

  const actionConstants = actions
    .map((action) => {
      const description = safeComment(action.description || action.title || action.id);
      return `  /** ${description} */\n  ${actionSymbol(action.id)}: ${JSON.stringify(action.id)},`;
    })
    .join("\n");
  const inputMap = typeMap(actions, "input_schema");
  const outputMap = typeMap(actions, "output_schema");

  return `/* eslint-disable */
/**
 * Generated by ActionParity from the executable Action Registry.
 * DO NOT EDIT. Change the Registry and regenerate this file.
 */

export const ACTION = {
${actionConstants}
} as const;

export type ActionId = (typeof ACTION)[keyof typeof ACTION];

export type ActionInputMap = {
${inputMap}
};

export type ActionOutputMap = {
${outputMap}
};

export type ActionRequest<A extends ActionId = ActionId> = {
  action_id: A;
  input: ActionInputMap[A];
  confirmed: boolean;
  execution_id?: string;
  surface?: string;
};

export type ActionError = {
  class: string;
  code: string;
  message: string;
  details?: unknown;
};

export type ActionEnvelope<A extends ActionId = ActionId> =
  | {
      ok: true;
      version: number;
      action_id: A;
      execution_id: string;
      result: ActionOutputMap[A];
      error?: never;
    }
  | {
      ok: false;
      version: number;
      action_id: A;
      execution_id: string;
      result?: never;
      error: ActionError;
    };

export type ActionCallOptions = {
  confirmed?: boolean;
  executionId?: string;
  surface?: string;
};

export type RawActionInvoker = (request: {
  action_id: string;
  input: unknown;
  confirmed: boolean;
  execution_id?: string;
  surface?: string;
}) => Promise<unknown>;

export function createActionClient(invoker: RawActionInvoker, defaults: { surface?: string } = {}) {
  return async function call<A extends ActionId>(
    actionId: A,
    input: ActionInputMap[A],
    options: ActionCallOptions = {},
  ): Promise<ActionEnvelope<A>> {
    const surface = options.surface ?? defaults.surface;
    const request: ActionRequest<A> = {
      action_id: actionId,
      input,
      confirmed: options.confirmed ?? false,
      ...(options.executionId === undefined ? {} : { execution_id: options.executionId }),
      ...(surface === undefined ? {} : { surface }),
    };
    return (await invoker(request)) as ActionEnvelope<A>;
  };
}

export type TauriInvoke = <T>(
  command: string,
  args?: Record<string, unknown>,
) => Promise<T>;

export type TauriActionClientOptions = {
  command?: string;
  requestArgument?: string;
  surface?: string;
};

export function createTauriActionClient(
  invoke: TauriInvoke,
  options: TauriActionClientOptions = {},
) {
  const command = options.command ?? "action_parity_call";
  const requestArgument = options.requestArgument ?? "request";
  return createActionClient(
    (request) => invoke(command, { [requestArgument]: request }),
    { surface: options.surface ?? "gui" },
  );
}
`;
}

export function jsonSchemaToType(schema, root = schema, refs = new Set()) {
  if (schema === true) return "unknown";
  if (schema === false) return "never";
  if (!schema || typeof schema !== "object") return "unknown";

  if (typeof schema.$ref === "string") {
    if (refs.has(schema.$ref)) return "unknown";
    const resolved = resolveLocalRef(root, schema.$ref);
    if (resolved === null) return "unknown";
    const nextRefs = new Set(refs);
    nextRefs.add(schema.$ref);
    return jsonSchemaToType(resolved, root, nextRefs);
  }
  if (Object.hasOwn(schema, "const")) return literalType(schema.const);
  if (Array.isArray(schema.enum) && schema.enum.length > 0) {
    return unique(schema.enum.map(literalType)).join(" | ");
  }

  for (const keyword of ["oneOf", "anyOf"]) {
    if (Array.isArray(schema[keyword]) && schema[keyword].length > 0) {
      return union(schema[keyword].map((item) => jsonSchemaToType(item, root, new Set(refs))));
    }
  }
  if (Array.isArray(schema.allOf) && schema.allOf.length > 0) {
    return unique(
      schema.allOf.map((item) => parenthesize(jsonSchemaToType(item, root, new Set(refs))))
    ).join(" & ");
  }

  if (Array.isArray(schema.type)) {
    return union(
      schema.type.map((type) => jsonSchemaToType({ ...schema, type }, root, new Set(refs)))
    );
  }

  let result;
  switch (schema.type) {
    case "null":
      result = "null";
      break;
    case "boolean":
      result = "boolean";
      break;
    case "integer":
    case "number":
      result = "number";
      break;
    case "string":
      result = "string";
      break;
    case "array":
      result = arrayType(schema, root, refs);
      break;
    case "object":
      result = objectType(schema, root, refs);
      break;
    default:
      if (schema.properties || Object.hasOwn(schema, "additionalProperties")) {
        result = objectType(schema, root, refs);
      } else if (schema.items || schema.prefixItems) {
        result = arrayType(schema, root, refs);
      } else {
        result = "unknown";
      }
  }
  return schema.nullable === true && result !== "null" ? `${parenthesize(result)} | null` : result;
}

function typeMap(actions, schemaField) {
  return actions
    .map((action) => {
      const schema = action[schemaField] ?? {};
      return `  ${JSON.stringify(action.id)}: ${jsonSchemaToType(schema)};`;
    })
    .join("\n");
}

function objectType(schema, root, refs) {
  const properties = schema.properties && typeof schema.properties === "object" ? schema.properties : {};
  const required = new Set(Array.isArray(schema.required) ? schema.required : []);
  const fields = Object.keys(properties)
    .sort()
    .map((name) => {
      const optional = required.has(name) ? "" : "?";
      return `${propertyName(name)}${optional}: ${jsonSchemaToType(properties[name], root, new Set(refs))};`;
    });

  if (schema.additionalProperties === true || schema.additionalProperties === undefined) {
    if (fields.length === 0) return "Record<string, unknown>";
    fields.push("[key: string]: unknown;");
  } else if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
    if (fields.length === 0) {
      return `Record<string, ${jsonSchemaToType(schema.additionalProperties, root, new Set(refs))}>`;
    }
    // TypeScript index signatures also constrain named properties, while JSON
    // Schema additionalProperties only constrains names not listed above.
    // Preserve known fields and safely widen only the extra keys.
    fields.push("[key: string]: unknown;");
  }

  if (fields.length === 0) return "Record<string, never>";
  return `{ ${fields.join(" ")} }`;
}

function arrayType(schema, root, refs) {
  if (Array.isArray(schema.prefixItems)) {
    const tuple = schema.prefixItems.map((item) => jsonSchemaToType(item, root, new Set(refs)));
    if (schema.items !== false) {
      tuple.push(`...Array<${jsonSchemaToType(schema.items ?? true, root, new Set(refs))}>`);
    }
    return `[${tuple.join(", ")}]`;
  }
  return `Array<${jsonSchemaToType(schema.items ?? {}, root, new Set(refs))}>`;
}

function resolveLocalRef(root, ref) {
  if (!ref.startsWith("#/")) return null;
  let current = root;
  for (const raw of ref.slice(2).split("/")) {
    const key = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (!current || typeof current !== "object" || !Object.hasOwn(current, key)) return null;
    current = current[key];
  }
  return current;
}

function actionSymbol(id) {
  return id.replace(/[^A-Za-z0-9]+/g, "_").replace(/^_+|_+$/g, "").toUpperCase();
}

function propertyName(name) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : JSON.stringify(name);
}

function literalType(value) {
  if (value === null || ["string", "number", "boolean"].includes(typeof value)) {
    return JSON.stringify(value);
  }
  return "unknown";
}

function union(types) {
  return unique(types.map(parenthesize)).join(" | ");
}

function parenthesize(type) {
  return type.includes(" | ") || type.includes(" & ") ? `(${type})` : type;
}

function unique(values) {
  return [...new Set(values)];
}

function safeComment(value) {
  return String(value).replaceAll("*/", "* /").replace(/\s+/g, " ").trim();
}
